static double captureAt;static MeadowRefinementStudy(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)return;try{if(File.Exists(Work+"meadow-refinement")){File.Delete(Work+"meadow-refinement");Run();}if(captureAt>0&&EditorApplication.timeSinceStartup>captureAt){captureAt=0;Capture();}}catch(Exception e){captureAt=0;Debug.LogException(e);}}
static T Save<T>(T obj,string path) where T:UnityEngine.Object {var old=AssetDatabase.LoadMainAssetAtPath(path);if(old){EditorUtility.CopySerialized(obj,old);UnityEngine.Object.DestroyImmediate(obj);return (T)old;}AssetDatabase.CreateAsset(obj,path);return obj;}
static float Noise(float x,float z)=>Mathf.PerlinNoise(x/14+19,z/14+37);
[MenuItem("CityForge/Ground Study/Refined Green Meadow")]
public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/GreenPatchPondStudy/GreenPatchPondZoom1.unity");var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var coverage=new Texture2D(2,2);coverage.LoadImage(File.ReadAllBytes("Assets/CityForge/Art/Environment/RollingPondStudy/GroundCoverage.png"));var shore=new Texture2D(2,2);shore.LoadImage(File.ReadAllBytes("Assets/CityForge/Art/Environment/RollingPondStudy/ShoreCoverage.png"));
var rnd=new System.Random(43927);float Random(float a,float b)=>Mathf.Lerp(a,b,(float)rnd.NextDouble());
bool Suitable(float x,float z){if(x<5||z<5||x>251||z>251||terrain.SampleHeight(new Vector3(x,0,z))<7.1f)return false;var c=coverage.GetPixelBilinear(x/256,z/256);return c.g<.025f&&c.b<.22f&&c.r<.85f;}
var vertices=new List<Vector3>();var triangles=new[]{new List<int>(),new List<int>(),new List<int>()};int patches=0,clumps=0,plants=0;
var plantRoot=new GameObject("Scattered low plants at meadow and woodland edges");
for(int attempt=0;attempt<1200&&patches<100;attempt++){float x=Random(8,248),z=Random(8,248);if(!Suitable(x,z)||Noise(x,z)<.43f)continue;var c=coverage.GetPixelBilinear(x/256,z/256);float bank=shore.GetPixelBilinear(x/256,z/256).g;if(c.r<.08f&&bank<.05f&&rnd.NextDouble()<.62)continue;patches++;float radius=Random(1.4f,3.6f);int shade=rnd.Next(3);
for(int j=0;j<100;j++){float angle=Random(0,6.283f),r=radius*Mathf.Sqrt(Random(0,1));float px=x+Mathf.Cos(angle)*r,pz=z+Mathf.Sin(angle)*r;if(!Suitable(px,pz))continue;clumps++;float height=Random(.25f,.60f)*(1-.25f*r/radius);var b=new Vector3(px,terrain.SampleHeight(new Vector3(px,0,pz))-.025f,pz);
for(int blade=0;blade<5;blade++){float a=Random(0,6.283f);var forward=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var side=new Vector3(-forward.z,0,forward.x)*Random(.045f,.08f);var mid=b+Vector3.up*height*.62f+forward*height*.17f;var tip=b+Vector3.up*height+forward*height*.42f;int q=vertices.Count;vertices.Add(b-side);vertices.Add(b+side);vertices.Add(mid-side*.65f);vertices.Add(mid+side*.65f);vertices.Add(tip);triangles[shade].AddRange(new[]{q,q+2,q+1,q+1,q+2,q+3,q+2,q+4,q+3});}}
if(patches%2==0){for(int j=0;j<2;j++){float px=x+Random(-radius,radius),pz=z+Random(-radius,radius);if(!Suitable(px,pz))continue;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/TerrainLookStudy/Shrub"+rnd.Next(3)+".prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.transform.SetParent(plantRoot.transform);go.transform.position=new Vector3(px,terrain.SampleHeight(new Vector3(px,0,pz))-.03f,pz);float scale=Random(.18f,.38f);go.transform.localScale=new Vector3(scale,scale*.7f,scale);go.transform.rotation=Quaternion.Euler(0,Random(0,360),0);plants++;}}}
var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.subMeshCount=3;for(int i=0;i<3;i++)mesh.SetTriangles(triangles[i],i);var normals=new Vector3[vertices.Count];for(int i=0;i<normals.Length;i++)normals[i]=Vector3.up;mesh.normals=normals;mesh.RecalculateBounds();var grass=new GameObject("Irregular clusters of taller meadow grass");grass.AddComponent<MeshFilter>().sharedMesh=Save(mesh,Root+"TallGrass.asset");var mats=new Material[3];Color[] colors={new Color(.11f,.22f,.065f),new Color(.19f,.31f,.085f),new Color(.25f,.34f,.11f)};for(int i=0;i<3;i++){var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.SetColor("_BaseColor",colors[i]);mat.SetFloat("_Cull",0);mat.SetFloat("_Smoothness",.03f);mats[i]=Save(mat,Root+"Grass"+i+".mat");}var renderer=grass.AddComponent<MeshRenderer>();renderer.sharedMaterials=mats;renderer.shadowCastingMode=ShadowCastingMode.Off;
var reflection=UnityEngine.Object.FindFirstObjectByType<PondPlanarReflection>();var previous=reflection.sourceCamera;previous.enabled=false;var main=new GameObject("Meadow presentation camera").AddComponent<Camera>();main.CopyFrom(previous);main.transform.rotation=previous.transform.rotation;main.transform.position=new Vector3(128,8,128)-main.transform.forward*300;main.nearClipPlane=.3f;main.farClipPlane=650;main.enabled=true;main.cameraType=CameraType.Game;main.ResetProjectionMatrix();main.ResetWorldToCameraMatrix();main.GetUniversalAdditionalCameraData().renderPostProcessing=true;reflection.sourceCamera=main;
UnityEngine.Object.DestroyImmediate(coverage);UnityEngine.Object.DestroyImmediate(shore);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"MeadowRefinementZoom1.unity");File.WriteAllText(Work+"meadow-refinement-result.txt",patches+" grass patches, "+clumps+" grass clumps, "+plants+" low plants. All placements exclude water and paths.\n");captureAt=EditorApplication.timeSinceStartup+3;}
static void Capture(){var reflection=UnityEngine.Object.FindFirstObjectByType<PondPlanarReflection>();reflection.RenderNow();var camera=reflection.sourceCamera;camera.rect=new Rect(0,0,1,1);camera.cullingMask=-1;camera.targetTexture=null;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.85f,.87f,.83f);camera.GetUniversalAdditionalCameraData().SetRenderer(0);camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;Debug.Log("Capture camera "+camera.name+" at "+camera.transform.position+" ortho "+camera.orthographicSize+" pipeline "+RenderPipelineManager.currentPipeline);var rt=new RenderTexture(3840,2160,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(3840,2160,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,3840,2160),0,0);t.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/MeadowRefinement_Zoom1.png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Debug.Log("MEADOW REFINEMENT CAPTURE COMPLETE");}
